import {renderPromptCenter} from './studio-methods.js';
import {esc,toast} from './components.js';
import {steps,clone,logJob} from './workflow-store.js';
import {modelGroups,modelGroup,resolveModel,validateModel} from './configuration-model.js';
export function settingsMarkup(){return '<dialog id="workflow-settings" class="dialog wide-dialog configuration-dialog" aria-labelledby="settings-title"></dialog>'}
export function bindSettings(s,persist,onChange){
 const dialog=document.querySelector('#workflow-settings');let kind='system',group='text',step=null,draft,dirty=false;const expandedGroups=new Set(['text']);
 const q=id=>dialog.querySelector('#'+id);
 function init(){draft={models:clone(s.models||{}),modelDefaults:clone(s.modelDefaults||{}),styles:clone(s.styles),styleIndex:s.styleIndex};dirty=false;}
 function hold(){if(kind==='system'&&q('model-name')&&!q('model-name').matches(':disabled')){const value={provider:q('provider').value,name:q('model-name').value,url:q('model-url').value,timeout:q('model-timeout').value,credentialRef:q('credential-ref').value,capability:group};const target=step?draft.models:draft.modelDefaults,key=step||group;if(JSON.stringify(value)!==JSON.stringify(target[key])&&(value.name||value.url)){target[key]=value;dirty=true;}}else if(kind==='styles'&&q('style-name')){draft.styles[draft.styleIndex]={name:q('style-name').value,text:q('style-text').value};}}
 function header(body,nav,footer){dialog.innerHTML=`<div class="panel-header"><div><p class="eyebrow">AI短片工坊 · 创作配置</p><h2 id="settings-title">设置</h2></div><button class="button" id="settings-close">关闭</button></div><div class="dialog-nav">${[['system','模型配置'],['prompts','提示词配置'],['styles','风格模板']].map(([k,n])=>`<button class="button ${kind===k?'primary':''}" data-settings-kind="${k}">${n}</button>`).join('')}</div><p class="config-help">本地交互演示。配置仅用于后续任务，历史结果保留快照；凭据只填写引用名称。</p><div class="configuration-layout"><nav class="configuration-menu" aria-label="配置场景">${nav}</nav><section class="configuration-body">${body}</section></div><p class="error-text" id="settings-error" role="alert"></p><div class="dialog-footer">${footer}</div>`;
 q('settings-close').onclick=()=>{hold();dialog.close();};dialog.oncancel=()=>hold();
 dialog.querySelectorAll('[data-settings-kind]').forEach(b=>b.onclick=()=>{hold();kind=b.dataset.settingsKind;if(kind==='system')step=null;draw();});
 return dialog;
 }
 function drawPrompt(selected='novel',options={}){step=selected;renderPromptCenter((title,body,footer)=>{header(body,Object.entries(steps).map(([id,n])=>`<button class="button ${id===step?'primary':''}" data-prompt-scene="${id}">${n}</button>`).join(''),footer);dialog.querySelectorAll('[data-prompt-scene]').forEach(b=>b.onclick=()=>drawPrompt(b.dataset.promptScene));return dialog;},selected,options.id,options.newTemplate);}
 function draw(){if(kind==='prompts'){drawPrompt(step&&steps[step]?step:'novel');return;}if(kind==='styles'){drawStyles();return;}
 const m=step?resolveModel(draft,step):(draft.modelDefaults[group]||{name:'',url:'',provider:'自定义服务',timeout:120,credentialRef:''}),inherit=!!step&&!draft.models[step];
 const nav=Object.entries(modelGroups).map(([id,n])=>`<button class="model-tree-node model-tree-parent ${group===id&&!step?'is-selected':''}" data-group="${id}" aria-expanded="${expandedGroups.has(id)}" aria-controls="model-children-${id}" ${group===id&&!step?'aria-current="true"':''} title="${draft.modelDefaults[id]?.name?'默认模型：'+esc(draft.modelDefaults[id].name):'未设置默认模型'}"><span class="model-tree-chevron" aria-hidden="true">${expandedGroups.has(id)?'⌄':'&gt;'}</span><span>${n}</span></button><div class="model-tree-children" id="model-children-${id}" ${expandedGroups.has(id)?'':'hidden'}>${Object.entries(steps).filter(([k])=>modelGroup(k)===id).map(([k,n])=>`<button class="model-tree-node model-tree-child ${step===k?'is-selected':''}" data-model-step="${k}" ${step===k?'aria-current="true"':''} title="${draft.models[k]?'独立配置':'继承类别默认'}">${n}</button>`).join('')}</div>`).join('');
 header(`<h3>${step?steps[step]:modelGroups[group]+' · 默认模型'}</h3><p class="helper">${step?'默认沿用所属类别的模型，仅在需要时为此环节单独配置。':'此类别下未单独配置的所有环节都会沿用此模型。'}</p>${step?`<label class="inherit-toggle"><input type="checkbox" id="inherit-model" ${inherit?'checked':''}>沿用${modelGroups[group]}默认模型</label><p class="helper">当前生效：${esc(m.source==='unconfigured'?'未配置，请先设置类别默认':m.name)} · ${inherit?'类别默认':'环节独立配置'}</p>`:''}<fieldset class="model-fields" ${inherit?'disabled':''}><div class="field-pair"><label class="field">服务商<input id="provider" value="${esc(m.provider||'')}"></label><label class="field">模型标识<input id="model-name" value="${esc(m.name==='演示模型'?'':m.name)}" placeholder="填写模型标识"></label></div><label class="field">服务地址<input id="model-url" type="url" value="${esc(m.url||'')}" placeholder="https://your-provider.example/api"></label><div class="field-pair"><label class="field">能力类型<input id="model-capability" value="${modelGroups[group]}" readonly></label><label class="field">超时秒数<input id="model-timeout" type="number" min="1" value="${esc(m.timeout||120)}"></label></div><label class="field">凭据引用名称<input id="credential-ref" value="${esc(m.credentialRef||'')}" placeholder="vault/my-provider"></label></fieldset>${group==='audio'?'<p class="helper">TTS 配音与配乐默认共用此路由；若服务支持的任务不同，可分别独立配置。音色、语速和情绪在台词配音时选择并记录。</p>':''}<button class="button" id="check-model">检查配置格式</button>`,nav,'<button class="button primary" id="settings-save">保存配置</button>');
 dialog.querySelector('.configuration-menu').classList.add('model-tree');dialog.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{hold();group=b.dataset.group;step=null;if(expandedGroups.has(group))expandedGroups.delete(group);else expandedGroups.add(group);draw();dialog.querySelector(`[data-group="${group}"]`).focus();});
 dialog.querySelectorAll('[data-model-step]').forEach(b=>b.onclick=()=>{hold();step=b.dataset.modelStep;group=modelGroup(step);draw();dialog.querySelector(`[data-model-step="${step}"]`).focus();});
 if(step)q('inherit-model').onchange=e=>{if(e.target.checked)delete draft.models[step];else draft.models[step]={...clone(draft.modelDefaults[group]||{name:'',url:'',timeout:120}),capability:group};dirty=true;draw();};
 q('check-model').onclick=()=>{hold();try{validateModel(step?resolveModel(draft,step):draft.modelDefaults[group],group);q('settings-error').textContent='格式检查通过；尚未进行网络连接与任务能力测试。';}catch(e){q('settings-error').textContent=e.message;}};
 q('settings-save').onclick=()=>{hold();try{for(const [g,m]of Object.entries(draft.modelDefaults))validateModel(m,g);for(const [k,m]of Object.entries(draft.models)){if(JSON.stringify(m)!==JSON.stringify(s.models?.[k]))validateModel(m,modelGroup(k));}s.models=clone(draft.models);s.modelDefaults=clone(draft.modelDefaults);s.configVersion++;if(!persist())return;dirty=false;dialog.close();onChange();toast('模型配置已保存，后续任务按类别默认或环节覆盖执行');}catch(e){q('settings-error').textContent=e.message;}};
 }
 function drawStyles(){const style=draft.styles[draft.styleIndex];header(`<h3>风格模板</h3><label class="field">模板名称<input id="style-name" value="${esc(style.name)}"></label><label class="field">风格描述 / 提示词<textarea id="style-text">${esc(style.text)}</textarea></label><div class="row"><button class="button" id="assist-style">AI 完善模板（演示）</button><button class="button" id="style-prompt">模板提示词</button></div><p class="helper">保存并选用后影响新的参考图和视频；已有素材标记待检查。</p>`,draft.styles.map((v,i)=>`<button class="button ${i===draft.styleIndex?'primary':''}" data-style-tab="${i}">${esc(v.name)}</button>`).join('')+'<button class="button" id="add-style">＋ 新建风格模板</button>','<button class="button primary" id="settings-save">保存并选用模板</button>');dialog.querySelectorAll('[data-style-tab]').forEach(b=>b.onclick=()=>{hold();draft.styleIndex=+b.dataset.styleTab;draw();});q('assist-style').onclick=()=>{q('style-text').value+='\n演示建议：统一人物服饰与色温，保持清晰主体与连贯镜头。';logJob(s,'template',{text:q('style-text').value});persist();};q('style-prompt').onclick=()=>{hold();kind='prompts';drawPrompt('template');};q('add-style').onclick=()=>{hold();draft.styles.push({name:'自定义风格 '+(draft.styles.length+1),text:''});draft.styleIndex=draft.styles.length-1;draw();};q('settings-save').onclick=()=>{hold();const v=draft.styles[draft.styleIndex];if(!v.name.trim()||!v.text.trim()){q('settings-error').textContent='请补全名称与描述';return;}const changed=JSON.stringify(s.styles[s.styleIndex])!==JSON.stringify(v);s.styles=clone(draft.styles);s.styleIndex=draft.styleIndex;if(changed){s.styleVersion++;s.chain.runId=null;if(s.chain.status==='running')s.chain.status='interrupted';s.shots.forEach(sh=>{sh.assets.forEach(a=>a.confirmed=false);sh.videoStale=!!sh.video;});}if(!persist())return;dialog.close();onChange();toast('风格模板已保存');};}
 return function open(k='system',selectedStep=null,options={}){if(!draft)init();hold();kind=k==='audio'?'system':k;if(k==='audio')selectedStep='voice';if(kind==='prompts')drawPrompt(selectedStep||'novel',options);else{step=selectedStep;group=step?modelGroup(step):group;if(step)expandedGroups.add(group);draw();}if(!dialog.open)dialog.showModal();};
}
